//! Original active Alpha Glow spatial fixtures.
use filmcraft_project::{Param,ParamValue};use filmcraft_render::{effects::{apply,FxCtx},image::Image};use serde_json::json;
fn main(){let mut cases=vec![];
for(w,h)in[(1,7),(7,1),(6,4),(18,10)]{for use_end in[false,true]{for fade_out in[false,true]{for(glow,brightness)in[(0.,252.),(0.6,255.),(2.5,100.),(100.,255.)]{for(sc,ec)in[([1.,1.,1.,1.],[1.,1.,1.,1.]),([-1.,2.,0.5,0.],[0.25,0.,2.,0.5])]{
let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect();let mut image=Image{w,h,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="alpha_glow").unwrap().instance();e.params.insert("use_end".into(),Param::new(ParamValue::Bool(use_end)));e.params.insert("fade_out".into(),Param::new(ParamValue::Bool(fade_out)));e.params.insert("start_color".into(),Param::new(ParamValue::Color(sc)));e.params.insert("end_color".into(),Param::new(ParamValue::Color(ec)));for(n,v)in[("glow",glow),("brightness",brightness)]{e.params.insert(n.into(),Param::new(ParamValue::Float(v)));}
let cx=FxCtx{t:filmcraft_time::Tick(0),px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut image,&e,&cx);cases.push(json!({"parameters":{"useEnd":use_end,"fadeOut":fade_out,"glow":glow,"brightness":brightness,"startColor":sc,"endColor":ec},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
}}}}}let mut media=vec![];
for use_end in[false,true]{for fade_out in[false,true]{for tick in[0u64,250000,500000]{
let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12{255}else{32};[v,v,v,if i%16<8&&i/16<12{128}else{0}]}).collect();let mut frames=vec![];
for index in 0..(1000000-tick).div_ceil(100000){let local=(tick+index*100000).min(500000);let t=local as f64/500000.;let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;let v=filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a;[v,v,v,a]}).collect();let mut frame=Image{w:16,h:16,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="alpha_glow").unwrap().instance();e.params.insert("use_end".into(),Param::new(ParamValue::Bool(use_end)));e.params.insert("fade_out".into(),Param::new(ParamValue::Bool(fade_out)));e.params.insert("start_color".into(),Param::new(ParamValue::Color([t as f32,(1.-t)as f32,(0.5*t)as f32,t as f32])));e.params.insert("end_color".into(),Param::new(ParamValue::Color([(1.-t)as f32,t as f32,(1.-0.5*t)as f32,(1.-t)as f32])));for(n,v)in[("glow",t*30.),("brightness",t*255.)]{e.params.insert(n.into(),Param::new(ParamValue::Float(v)));}
let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut frame,&e,&cx);frames.push(frame.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}
media.push(json!({"useEnd":use_end,"fadeOut":fade_out,"localTick":tick,"rgba":rgba,"bits":frames[0],"frames":frames}));
}}}println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));}
